/* ============================================================
   MİRAS FC — HİKÂYE AĞACI
   Olaylar kimlikle tanımlanır; kayıtta yalnızca {id, x, t} durur.
   Seçenek: { l: etiket (metin ya da x=>metin), d: açıklama, f: (x)=>etki,
              v: [Hırs, Sadakat, Aile, Para] değer değişimi, if: ()=>görünür mü }
   Olay: { id, a:[minYaş,maxYaş], f: koşul, once, cd: tekrar için yıl,
           w: ağırlık, pre: ()=>x (kaydedilecek veri), t: metin ya da x=>metin, c: [...] }
   ============================================================ */
const up = (k, d) => { g.st[k] = clr(g.st[k] + d, 1, Math.min(99, g.cap[k])); };
const relAdj = (p, d) => { if (p) p.rel = clr((p.rel || 60) + d, 0, 100); };
const friend = i => (g.friends || [])[i || 0];
const aliveParent = () => [g.fam.father, g.fam.mother].filter(p => p.alive);
let MCTX = '';
const money = (d, why) => {
  g.money += d; if (!d || !Number.isFinite(d)) return;
  const L2 = g.ledger || (g.ledger = []), k = why || MCTX || (d > 0 ? 'Diğer gelir' : 'Diğer harcama'), stamp = g.season * 100 + (g.week || 0), top = L2[0];
  if (top && top.k === k && top.s === stamp) top.v += d; else { L2.unshift({ s: stamp, y: g.season, w: g.week || 0, k, v: d }); if (L2.length > 80) L2.length = 80; }
  if (Math.abs(d) >= 1) g.lastD = { v: Math.round(d), k, t: Date.now() };
};
const famCost = k => Math.round(k * cinfo(g.ct).e);

