function idolPick() { const all = Object.values(STARS).flat().filter(x => /\|(FW|MF)\|(8[5-9]|9\d)\|/.test(x)); return P(all).split('|')[0]; }
function setAcad(c, lv) { if (!c) return; g.acad = lv; g.acadClub = { id: c.id, n: c.n, ct: clubCt(c.id) }; L(`${clubName(c.n)} altyapısına katıldın.`); }

